class CsvError(Exception):
    def __init__(self, message, line, col):
        super().__init__(message)
        self.line = line
        self.col = col


def _is_int(s):
    if not s:
        return False
    i = 0
    if s[0] == '-':
        i = 1
    if i >= len(s):
        return False
    for ch in s[i:]:
        if ch < '0' or ch > '9':
            return False
    return True


def _parse_field(text, i, n, line, col, delimiter, quote, escape, skip_initial_space, strict):
    # Rule 6: skip initial spaces
    if skip_initial_space:
        while i < n and text[i] == ' ':
            i += 1
            col += 1

    # Rule 7: check if quoted
    if quote is not None and i < n and text[i] == quote:
        quote_start_line = line
        quote_start_col = col
        i += 1
        col += 1
        content = []

        while True:
            if i >= n:
                raise CsvError("Unterminated quoted field", quote_start_line, quote_start_col)

            ch = text[i]

            if escape is not None:
                if ch == escape:
                    i += 1
                    col += 1
                    if i >= n:
                        raise CsvError("Unterminated quoted field", quote_start_line, quote_start_col)
                    x = text[i]
                    content.append(x)
                    if x == '\n':
                        i += 1
                        line += 1
                        col = 1
                    elif x == '\r':
                        i += 1
                        line += 1
                        col = 1
                    else:
                        i += 1
                        col += 1
                    continue
                elif ch == quote:
                    i += 1
                    col += 1
                    break
                elif ch == '\n':
                    content.append('\n')
                    i += 1
                    line += 1
                    col = 1
                    continue
                elif ch == '\r':
                    if i + 1 < n and text[i + 1] == '\n':
                        content.append('\r\n')
                        i += 2
                        line += 1
                        col = 1
                    else:
                        content.append('\r')
                        i += 1
                        line += 1
                        col = 1
                    continue
                else:
                    content.append(ch)
                    i += 1
                    col += 1
                    continue
            else:
                if ch == quote:
                    if i + 1 < n and text[i + 1] == quote:
                        content.append(quote)
                        i += 2
                        col += 2
                        continue
                    else:
                        i += 1
                        col += 1
                        break
                elif ch == '\n':
                    content.append('\n')
                    i += 1
                    line += 1
                    col = 1
                    continue
                elif ch == '\r':
                    if i + 1 < n and text[i + 1] == '\n':
                        content.append('\r\n')
                        i += 2
                        line += 1
                        col = 1
                    else:
                        content.append('\r')
                        i += 1
                        line += 1
                        col = 1
                    continue
                else:
                    content.append(ch)
                    i += 1
                    col += 1
                    continue

        field = ''.join(content)

        # Rule 9: tail check
        if i < n and text[i] != delimiter and text[i] != '\n' and text[i] != '\r':
            if strict:
                raise CsvError("Tail after closing quote", line, col)
            else:
                while i < n and text[i] != delimiter and text[i] != '\n' and text[i] != '\r':
                    field += text[i]
                    i += 1
                    col += 1

        return field, True, i, line, col

    # Unquoted field
    content = []
    while i < n:
        ch = text[i]
        if ch == delimiter or ch == '\n' or ch == '\r':
            break
        content.append(ch)
        i += 1
        col += 1

    return ''.join(content), False, i, line, col


def _apply_rule10(val, is_quoted, trim, null_values, infer_ints):
    if is_quoted:
        return val
    if trim:
        val = val.strip(' \t')
    if val in null_values:
        return None
    if infer_ints and _is_int(val):
        return int(val)
    return val


def parse(text: str, dialect: dict) -> list:
    delimiter = dialect.get("delimiter", ",")
    quote = dialect.get("quote", '"')
    escape = dialect.get("escape", None)
    skip_initial_space = dialect.get("skip_initial_space", False)
    comment = dialect.get("comment", None)
    skip_blank = dialect.get("skip_blank", True)
    strict = dialect.get("strict", True)
    header = dialect.get("header", False)
    fill = dialect.get("fill", None)
    null_values = dialect.get("null_values", [])
    infer_ints = dialect.get("infer_ints", False)
    trim = dialect.get("trim", False)

    # Rule 1
    if text.startswith('\ufeff'):
        text = text[1:]

    # Rule 2
    if text == '':
        return []

    n = len(text)
    i = 0
    line = 1
    col = 1
    raw_records = []

    while i < n:
        # Rule 3: blank line
        if text[i] == '\n' or text[i] == '\r':
            if not skip_blank:
                raw_records.append([('', False)])
            if text[i] == '\r' and i + 1 < n and text[i + 1] == '\n':
                i += 2
            else:
                i += 1
            line += 1
            col = 1
            continue

        # Rule 4: comment line
        if comment is not None and text[i] == comment:
            while i < n and text[i] != '\n' and text[i] != '\r':
                i += 1
                col += 1
            if i < n:
                if text[i] == '\r' and i + 1 < n and text[i + 1] == '\n':
                    i += 2
                else:
                    i += 1
                line += 1
                col = 1
            continue

        # Parse a record
        record = []
        while True:
            field_val, is_quoted, i, line, col = _parse_field(
                text, i, n, line, col,
                delimiter, quote, escape, skip_initial_space, strict
            )
            record.append((field_val, is_quoted))

            if i >= n:
                break

            ch = text[i]
            if ch == '\r' or ch == '\n':
                if ch == '\r' and i + 1 < n and text[i + 1] == '\n':
                    i += 2
                else:
                    i += 1
                line += 1
                col = 1
                break
            elif ch == delimiter:
                i += 1
                col += 1
            else:
                break

        raw_records.append(record)

    # Header handling (rules 11 & 12)
    if header and raw_records:
        header_raw = raw_records[0]
        data_raw = raw_records[1:]

        # Build header names
        names = []
        for idx, (val, _) in enumerate(header_raw):
            name = val
            if name == '':
                name = f'col{idx + 1}'
            names.append(name)

        # Deduplicate
        name_counts = {}
        final_names = []
        for name in names:
            k = name_counts.get(name, 0)
            if k >= 1:
                final_names.append(f'{name}_{k + 1}')
            else:
                final_names.append(name)
            name_counts[name] = k + 1

        result = []
        for record in data_raw:
            d = {}
            num_header = len(final_names)
            for j in range(num_header):
                if j < len(record):
                    val, is_quoted = record[j]
                    d[final_names[j]] = _apply_rule10(val, is_quoted, trim, null_values, infer_ints)
                else:
                    d[final_names[j]] = fill
            if len(record) > num_header:
                extras = []
                for j in range(num_header, len(record)):
                    val, is_quoted = record[j]
                    extras.append(_apply_rule10(val, is_quoted, trim, null_values, infer_ints))
                d['_extra'] = extras
            result.append(d)
        return result
    else:
        result = []
        for record in raw_records:
            processed = []
            for val, is_quoted in record:
                processed.append(_apply_rule10(val, is_quoted, trim, null_values, infer_ints))
            result.append(processed)
        return result
